use std::collections::BTreeMap;
use std::sync::Arc;
use std::sync::RwLock;
use std::time::Duration;
use std::time::Instant;

use aes::Aes128;
use aes::cipher::Array;
use aes::cipher::BlockCipherDecrypt;
use aes::cipher::BlockCipherEncrypt;
use aes::cipher::KeyInit;
use aws_lc_rs::rand::SecureRandom;
use aws_lc_rs::rand::SystemRandom;
use aws_lc_rs::signature::KeyPair;
use aws_lc_rs::signature::RSA_PKCS1_2048_8192_SHA256;
use aws_lc_rs::signature::RSA_PKCS1_SHA256;
use aws_lc_rs::signature::RsaKeyPair;
use sha2::Digest;
use sha2::Sha256;
use tokio::sync::Notify;
use x509_parser::prelude::*;

use crate::state::PersistentState;

/// A client that is not yet paired, but in the pairing process.
pub(crate) struct PendingClient {
	/// Unique id of the client.
	pub(crate) id: String,

	/// Human-readable name Moonlight sent as `devicename`, when it sent one.
	pub(crate) name: Option<String>,

	/// Display label for the peer that opened this pairing connection: a
	/// reverse-DNS hostname when one resolved, otherwise the bare IP as a
	/// string (see `webserver::reverse_dns::resolve_label`, which computes
	/// this once at registration time). Every Moonlight client hardcodes
	/// both `devicename` and, absent `m_UseTrueUid`, `uniqueid` too, so on a
	/// home LAN this is often the only thing that actually distinguishes one
	/// pairing client from another. The port is deliberately not kept: it is
	/// ephemeral per connection and would just be noise in the on-device UI.
	pub(crate) address: Option<String>,

	/// Client certificate used for secure communication (PEM format).
	pub(crate) pem: String,

	/// Salt provided by the client to use for encryption.
	pub(crate) salt: [u8; 16],

	/// A channel that sends a notification when a PIN has been received for this client.
	pub(crate) pin_notify: Arc<Notify>,

	/// Cryptographic key.
	pub(crate) key: Option<[u8; 16]>,

	/// Server secret as generated by the server.
	pub(crate) server_secret: Option<[u8; 16]>,

	/// Server challenge provided by the client.
	pub(crate) server_challenge: Option<[u8; 16]>,

	/// Cryptographic hash.
	pub(crate) client_hash: Option<Vec<u8>>,

	/// When this client was registered as pending. Used to expire entries
	/// that have sat waiting for a PIN longer than [`PENDING_CLIENT_TTL`].
	pub(crate) created_at: Instant,
}

/// How long a client may sit in the pending-pairing set before it is expired
/// as a backstop.
///
/// The normal removal paths are: pairing completes successfully, or the
/// pairing HTTP connection is dropped mid-request and [`PendingClientGuard`]
/// cleans up immediately. This TTL only matters when neither happens — e.g.
/// the handheld's WiFi drops, the phone/PC sleeps, or a NAT keeps the TCP
/// socket alive without the peer actually being there to finish pairing.
///
/// Pairing is a human-paced action: someone has to notice the request, pick
/// up the handheld, wake it, navigate to the Cast pairing screen, and type a
/// 4-digit PIN. Anything under a minute risks cutting off a real attempt, so
/// this is deliberately generous.
const PENDING_CLIENT_TTL: Duration = Duration::from_secs(5 * 60);

/// A client waiting for a PIN, as shown by the on-device UI.
#[derive(Clone, Debug)]
pub struct PendingInfo {
	pub id: String,
	pub name: Option<String>,

	/// Display label for the peer that opened this pairing connection: a
	/// reverse-DNS hostname when one resolved, otherwise the bare IP as a
	/// string (no port). `None` if the peer address could not be
	/// determined.
	pub address: Option<String>,
}

/// An already-paired client, as shown by the on-device UI's paired-devices
/// list. Keyed on `fingerprint`, not a client id: every real Moonlight
/// client hardcodes `uniqueid=0123456789ABCDEF` unless a build opts into a
/// true unique id (`m_UseTrueUid`, off by default), so two different
/// machines can and do share one `uniqueid` — the client certificate's
/// SHA-256 fingerprint is the only thing here that actually distinguishes
/// one paired machine from another.
///
/// `name`/`address` are a snapshot of [`PendingClient::name`]/
/// [`PendingClient::address`] taken the moment pairing completed, not a
/// live lookup — DHCP churn after that can make either stale, and two
/// entries can legitimately show the same label if two machines paired
/// from the same address at different times. The fingerprint is what stays
/// true; the label is best-effort for a human to recognize the row.
#[derive(Clone, Debug)]
pub struct PairedInfo {
	pub fingerprint: String,
	pub name: Option<String>,
	pub address: Option<String>,
}

/// Manages client pairing state and operations.
///
/// This is a synchronous manager backed by an `Arc<RwLock>`. It holds pending client state
/// (salt, certificates, challenge/response data) and delegates persistent state to `State`.
#[derive(Clone)]
pub struct ClientManager {
	pending_clients: Arc<RwLock<BTreeMap<String, PendingClient>>>,

	/// Fires whenever the pending set changes, so a subscriber can push a
	/// fresh snapshot instead of polling. Also fires on every paired-list
	/// change (pairing completing, or [`ClientManager::unpair`]) — the name
	/// predates the paired list, but it is the one "something the on-device
	/// UI shows just changed" signal this crate has, and reusing it means
	/// callers only ever have to watch one `Notify`.
	pending_changed: Arc<Notify>,

	state: PersistentState,
	server_cert_pem: String,
	server_private_key_pem: String,
}

impl ClientManager {
	pub fn new(server_cert_pem: String, server_private_key_pem: String) -> Result<Self, ()> {
		Ok(Self {
			pending_clients: Arc::new(RwLock::new(BTreeMap::new())),
			pending_changed: Arc::new(Notify::new()),
			state: PersistentState::new()?,
			server_cert_pem,
			server_private_key_pem,
		})
	}

	/// Clients waiting for a PIN. The on-device UI lists these.
	///
	/// Opportunistically sweeps expired entries first (see
	/// [`PENDING_CLIENT_TTL`]) so a client that vanished without dropping its
	/// TCP connection doesn't linger forever just because nothing else
	/// touched the pending set.
	pub fn pending_clients(&self) -> Vec<PendingInfo> {
		if self.expire_stale_pending() {
			self.pending_changed.notify_waiters();
		}

		let Ok(inner) = self.pending_clients.read() else {
			tracing::error!("RwLock poisoned reading pending clients");
			return Vec::new();
		};
		inner
			.values()
			.map(|c| PendingInfo {
				id: c.id.clone(),
				name: c.name.clone(),
				address: c.address.clone(),
			})
			.collect()
	}

	/// Remove pending clients that have waited longer than
	/// [`PENDING_CLIENT_TTL`]. Returns `true` if anything was removed.
	fn expire_stale_pending(&self) -> bool {
		let Ok(mut inner) = self.pending_clients.write() else {
			tracing::error!("RwLock poisoned expiring pending clients");
			return false;
		};
		let before = inner.len();
		inner.retain(|_, client| client.created_at.elapsed() < PENDING_CLIENT_TTL);
		inner.len() != before
	}

	/// Remove a pending client by id, e.g. because its pairing request was
	/// abandoned. Returns `true` if it was present. Does not signal
	/// `pending_changed` itself; callers that care (like
	/// [`PendingClientGuard`]) do so explicitly.
	fn remove_pending(&self, id: &str) -> bool {
		let Ok(mut inner) = self.pending_clients.write() else {
			tracing::error!("RwLock poisoned removing pending client");
			return false;
		};
		inner.remove(id).is_some()
	}

	/// Fires whenever the pending set changes, so a subscriber can push a
	/// fresh snapshot instead of polling.
	pub fn pending_changed(&self) -> Arc<Notify> {
		self.pending_changed.clone()
	}

	/// Insert a pending client, signal the change, and return the `Notify`
	/// that fires once a PIN has been received for it.
	///
	/// `address` is the already-resolved display label (see
	/// [`PendingClient::address`]), not a raw IP - resolving it is an async,
	/// blocking-pool operation, so callers do that before calling in here.
	pub(crate) fn add_pending(
		&self,
		id: String,
		pem: String,
		salt: [u8; 16],
		name: Option<String>,
		address: Option<String>,
	) -> Arc<Notify> {
		let pin_notify = Arc::new(Notify::new());
		if let Ok(mut inner) = self.pending_clients.write() {
			inner.insert(
				id.clone(),
				PendingClient {
					id,
					name,
					address,
					pem,
					salt,
					pin_notify: pin_notify.clone(),
					key: None,
					server_secret: None,
					server_challenge: None,
					client_hash: None,
					created_at: Instant::now(),
				},
			);
		} else {
			tracing::error!("RwLock poisoned inserting pending client");
		}
		self.pending_changed.notify_waiters();
		pin_notify
	}

	pub fn persistent_state(&self) -> &PersistentState {
		&self.state
	}

	pub(crate) fn is_paired(&self, id: String) -> Result<bool, ()> {
		self.state.has_client(id)
	}

	pub(crate) fn is_cert_paired(&self, fingerprint: &str) -> Result<bool, ()> {
		self.state.has_paired_cert(fingerprint.to_string())
	}

	/// Every paired client, for the on-device UI's paired-devices list.
	/// Empty (rather than an error) if the state lock is poisoned, same
	/// fail-open-to-empty precedent as [`Self::pending_clients`].
	pub fn paired_clients(&self) -> Vec<PairedInfo> {
		self.state
			.paired_certs()
			.unwrap_or_else(|()| {
				tracing::error!("Failed to read paired certs");
				Vec::new()
			})
			.into_iter()
			.map(|(fingerprint, name, address)| PairedInfo { fingerprint, name, address })
			.collect()
	}

	/// Unpair a client by certificate fingerprint (see [`PairedInfo`] for
	/// why that, not a client id, is the key). Returns `true` if it was
	/// paired and is now removed, `false` if it was already not paired.
	/// Signals [`Self::pending_changed`] on an actual removal, so the
	/// on-device UI's paired list updates live, the same as pairing
	/// completing does.
	pub fn unpair(&self, fingerprint: &str) -> Result<bool, ()> {
		let removed = self.state.remove_paired_cert(fingerprint)?;
		if removed {
			self.pending_changed.notify_waiters();
		}
		Ok(removed)
	}

	pub fn register_pin(&self, id: &str, pin: &str) -> Result<(), ()> {
		let mut inner = self.pending_clients.write().map_err(|poison| {
			tracing::error!("RwLock poisoned: {poison}");
		})?;
		let client = inner.get_mut(id).ok_or_else(|| {
			tracing::warn!("No known client with id {id}");
		})?;
		let key = create_key(&client.salt, pin).map_err(|e| tracing::warn!("Failed to create client key: {e}"))?;
		client.key = Some(key);
		client.pin_notify.notify_waiters();
		drop(inner);
		self.pending_changed.notify_waiters();
		Ok(())
	}

	pub(crate) fn client_challenge(&self, id: &str, challenge: Vec<u8>) -> Result<Vec<u8>, ()> {
		let mut inner = self.pending_clients.write().map_err(|poison| {
			tracing::error!("RwLock poisoned: {poison}");
		})?;
		let client = inner.get_mut(id).ok_or_else(|| {
			tracing::warn!("No known client with id {id}");
		})?;

		let key = match &client.key {
			Some(key) => key,
			None => {
				tracing::warn!("Client has not provided a pin yet.");
				return Err(());
			},
		};

		let mut server_secret = [0u8; 16];
		SystemRandom::new()
			.fill(&mut server_secret)
			.map_err(|_| tracing::warn!("Failed to generate random"))?;
		client.server_secret = Some(server_secret);

		let mut decrypted =
			aes_decrypt_ecb(&challenge, key).map_err(|e| tracing::warn!("Failed to decrypt client challenge: {e}"))?;

		let signature_bytes = extract_certificate_signature(&self.server_cert_pem)
			.map_err(|e| tracing::warn!("Failed to extract server cert signature: {e}"))?;
		decrypted.extend_from_slice(&signature_bytes);
		decrypted.extend_from_slice(&server_secret);

		let mut server_challenge = [0u8; 16];
		SystemRandom::new()
			.fill(&mut server_challenge)
			.map_err(|_| tracing::warn!("Failed to generate random"))?;
		client.server_challenge = Some(server_challenge);

		let mut hasher = Sha256::new();
		hasher.update(&decrypted);
		let challenge_response_hash = hasher.finalize();

		let mut challenge_response_decrypted = challenge_response_hash.to_vec();
		challenge_response_decrypted.extend(server_challenge);

		let response = aes_encrypt_ecb(&challenge_response_decrypted, key)
			.map_err(|e| tracing::warn!("Failed to encrypt client challenge response: {e}"))?;
		drop(inner);
		self.pending_changed.notify_waiters();
		Ok(response)
	}

	pub(crate) fn server_challenge_response(&self, id: &str, challenge_response: Vec<u8>) -> Result<Vec<u8>, ()> {
		let mut inner = self.pending_clients.write().map_err(|poison| {
			tracing::error!("RwLock poisoned: {poison}");
		})?;
		let client = inner.get_mut(id).ok_or_else(|| {
			tracing::warn!("No known client with id {id}");
		})?;

		let key = match &client.key {
			Some(key) => key,
			None => {
				tracing::warn!("Client has not provided a pin yet.");
				return Err(());
			},
		};

		let decrypted = aes_decrypt_ecb(&challenge_response, key)
			.map_err(|e| tracing::warn!("Failed to decrypt server challenge response: {e}"))?;
		client.client_hash = Some(decrypted);

		let server_secret = client.server_secret.ok_or_else(|| {
			tracing::warn!("Client does not have a server secret.");
		})?;

		let mut pairing_secret = server_secret.to_vec();
		let signed = sign(&server_secret, &self.server_private_key_pem)
			.map_err(|e| tracing::warn!("Failed to sign server secret: {e}"))?;
		pairing_secret.extend(signed);

		drop(inner);
		self.pending_changed.notify_waiters();
		Ok(pairing_secret)
	}

	pub(crate) fn check_client_pairing_secret(&self, id: &str, client_secret: Vec<u8>) -> Result<(), ()> {
		let mut inner = self.pending_clients.write().map_err(|poison| {
			tracing::error!("RwLock poisoned: {poison}");
		})?;
		let client = inner.get_mut(id).ok_or_else(|| {
			tracing::warn!("No known client with id {id}");
		})?;
		verify_pairing_secret(client, client_secret)
			.map_err(|e| tracing::warn!("Failed to verify client pairing secret: {e}"))?;

		let fingerprint = cert_pem_fingerprint(&client.pem);
		if let Some(fp) = &fingerprint {
			// Label the fingerprint with whatever this pending client had at
			// the moment it paired — see `PairedInfo`'s doc comment: this is
			// the only point where that label is available, since pairing
			// completing is also what removes the `PendingClient` it lives
			// on (`inner.remove(id)` below).
			self.state
				.add_paired_cert(fp.clone(), client.name.clone(), client.address.clone())
				.map_err(|_| tracing::warn!("Failed to persist paired certificate: {fp}"))?;
		}

		let has_client = self
			.state
			.has_client(id.to_string())
			.map_err(|_| tracing::warn!("Failed to check client paired status"))?;
		if !has_client {
			self.state
				.add_client(id.to_string())
				.map_err(|_| tracing::warn!("Failed to persist client '{id}'"))?;
		}

		// Pairing is complete: the client is no longer pending. Remove it so
		// the on-device UI doesn't keep listing a client that already paired.
		inner.remove(id);
		drop(inner);
		self.pending_changed.notify_waiters();
		Ok(())
	}
}

/// Removes a pending client on drop, unless [`disarm`](Self::disarm) is
/// called first.
///
/// This guards the live-request `getservercert` phase of pairing
/// (`handle_pair_request` in `webserver/pairing.rs`), which parks inside the
/// HTTP handler awaiting a PIN for as long as it takes the user to walk over
/// and type one in. If Moonlight is quit, or the connection otherwise drops,
/// hyper cancels that handler future — which drops this guard along with it,
/// removing the now-orphaned pending entry and firing `pending_changed` so
/// the on-device UI updates immediately, without waiting on
/// [`PENDING_CLIENT_TTL`].
///
/// On the success path (a PIN was received), call `disarm()`: pairing
/// continues over further HTTP requests, and the entry must stay pending
/// until `check_client_pairing_secret` removes it for real.
pub(crate) struct PendingClientGuard {
	id: String,
	client_manager: ClientManager,
	armed: bool,
}

impl PendingClientGuard {
	pub(crate) fn new(client_manager: ClientManager, id: String) -> Self {
		Self {
			id,
			client_manager,
			armed: true,
		}
	}

	/// Prevent this guard's `Drop` from removing the pending client.
	pub(crate) fn disarm(mut self) {
		self.armed = false;
	}
}

impl Drop for PendingClientGuard {
	fn drop(&mut self) {
		if !self.armed {
			return;
		}
		if self.client_manager.remove_pending(&self.id) {
			self.client_manager.pending_changed.notify_waiters();
		}
	}
}

fn create_key(salt: &[u8; 16], pin: &str) -> Result<[u8; 16], String> {
	let mut key = Vec::with_capacity(salt.len() + pin.len());
	key.extend(salt);
	key.extend(pin.as_bytes());

	let mut hasher = Sha256::new();
	hasher.update(&key);
	let hash = hasher.finalize();

	hash[..16]
		.try_into()
		.map_err(|e| format!("Received unexpected key result: {e}"))
}

fn sign(data: &[u8], key_pem: &str) -> Result<Vec<u8>, String> {
	let key_bytes = {
		let mut reader = std::io::Cursor::new(key_pem.as_bytes());
		match rustls_pemfile::private_key(&mut reader) {
			Ok(Some(key)) => key.secret_der().to_vec(),
			Ok(None) => return Err("No key found in PEM".to_string()),
			Err(e) => return Err(format!("Failed to parse key PEM: {}", e)),
		}
	};

	let key_pair = RsaKeyPair::from_pkcs8(&key_bytes).map_err(|e| format!("Failed to load RSA key pair: {}", e))?;

	let rng = SystemRandom::new();
	let mut signature = vec![0; key_pair.public_key().modulus_len()];

	key_pair
		.sign(&RSA_PKCS1_SHA256, &rng, data, &mut signature)
		.map_err(|e| format!("Failed to sign data: {}", e))?;
	Ok(signature)
}

fn extract_certificate_signature(pem: &str) -> Result<Vec<u8>, String> {
	let (_, pem_obj) = parse_x509_pem(pem.as_bytes()).map_err(|e| format!("Failed to parse PEM: {}", e))?;
	let cert = pem_obj
		.parse_x509()
		.map_err(|e| format!("Failed to parse X509: {}", e))?;
	Ok(cert.signature_value.data.to_vec())
}

fn verify_client_signature(pem: &str, secret: &[u8], signature: &[u8]) -> Result<(), String> {
	let (_, pem_obj) = parse_x509_pem(pem.as_bytes()).map_err(|e| format!("Failed to parse PEM: {}", e))?;
	let cert = pem_obj
		.parse_x509()
		.map_err(|e| format!("Failed to parse X509: {}", e))?;
	let public_key_bytes = cert.tbs_certificate.subject_pki.subject_public_key.data;
	let public_key = aws_lc_rs::signature::UnparsedPublicKey::new(&RSA_PKCS1_2048_8192_SHA256, public_key_bytes);
	public_key.verify(secret, signature).map_err(|_| {
		"Client certificate signature verification failed: signature does not match the client's public key".to_string()
	})
}

fn verify_pairing_secret(client: &mut PendingClient, client_secret: Vec<u8>) -> Result<(), String> {
	let client_hash = match &client.client_hash {
		Some(client_hash) => client_hash,
		None => return Err("We did not yet receive a client hash.".to_string()),
	};

	let server_challenge = match client.server_challenge {
		Some(server_challenge) => server_challenge,
		None => {
			return Err("Client does not have a server challenge, possibly incorrect pairing procedure?".to_string());
		},
	};

	if client_secret.len() < 16 {
		return Err(format!(
			"Expected client pairing secret to be at least 16 bytes, but got {}",
			client_secret.len()
		));
	}

	let client_secret_payload = &client_secret[..16];
	let client_signature = &client_secret[16..];

	let mut data = server_challenge.to_vec();

	let signature_bytes = extract_certificate_signature(&client.pem)
		.map_err(|e| format!("Failed to extract client cert signature: {e}"))?;
	data.extend(signature_bytes);
	data.extend(client_secret_payload);

	let mut hasher = Sha256::new();
	hasher.update(&data);
	let hash = hasher.finalize();

	if !hash.to_vec().eq(client_hash) {
		return Err("Client hash is not as expected, MITM?".to_string());
	}

	verify_client_signature(&client.pem, client_secret_payload, client_signature)?;

	Ok(())
}

fn aes_encrypt_ecb(data: &[u8], key: &[u8; 16]) -> Result<Vec<u8>, String> {
	let key: Array<u8, _> = (*key).into();
	let cipher = Aes128::new(&key);
	if !data.len().is_multiple_of(16) {
		return Err(format!("Data length {} not a multiple of 16", data.len()));
	}

	let mut encrypted = data.to_vec();
	for block in encrypted.chunks_mut(16) {
		let gblock: &mut aes::cipher::Array<u8, _> = block.try_into().map_err(|_| "Invalid block length")?;
		cipher.encrypt_block(gblock);
	}
	Ok(encrypted)
}

fn aes_decrypt_ecb(data: &[u8], key: &[u8; 16]) -> Result<Vec<u8>, String> {
	let key: Array<u8, _> = (*key).into();
	let cipher = Aes128::new(&key);
	if !data.len().is_multiple_of(16) {
		return Err(format!("Data length {} not a multiple of 16", data.len()));
	}

	let mut decrypted = data.to_vec();
	for block in decrypted.chunks_mut(16) {
		let gblock: &mut aes::cipher::Array<u8, _> = block.try_into().map_err(|_| "Invalid block length")?;
		cipher.decrypt_block(gblock);
	}
	Ok(decrypted)
}

fn cert_pem_fingerprint(pem: &str) -> Option<String> {
	let (_, pem_obj) = parse_x509_pem(pem.as_bytes()).ok()?;
	Some(hex::encode(Sha256::digest(&pem_obj.contents)))
}

#[cfg(test)]
mod pending_tests {
	use super::*;

	fn salt() -> [u8; 16] {
		[0u8; 16]
	}

	// `ClientManager::new()` in the real codebase takes the server's cert and
	// key PEM strings and returns a `Result` (they're only ever stored, never
	// parsed at construction time, so dummy values are fine here).
	fn manager() -> ClientManager {
		ClientManager::new(String::new(), String::new()).expect("construct ClientManager")
	}

	#[test]
	fn pending_clients_lists_id_and_name() {
		let m = manager();
		m.add_pending("AABB".into(), "pem".into(), salt(), Some("eric-mbp".into()), None);
		let listed = m.pending_clients();
		assert_eq!(listed.len(), 1);
		assert_eq!(listed[0].id, "AABB");
		assert_eq!(listed[0].name.as_deref(), Some("eric-mbp"));
	}

	#[test]
	fn pending_clients_tolerates_a_missing_name() {
		let m = manager();
		m.add_pending("CCDD".into(), "pem".into(), salt(), None, None);
		assert_eq!(m.pending_clients()[0].name, None);
	}

	#[test]
	fn pending_clients_lists_the_address_label_it_was_given() {
		// `add_pending` takes an already-resolved label (see
		// `webserver::reverse_dns::resolve_label`), which is either a
		// reverse-DNS hostname or, absent one, the bare IP as a string. This
		// just checks `ClientManager` passes whatever it's given straight
		// through - resolution itself is tested in `reverse_dns`.
		let m = manager();
		m.add_pending("1122".into(), "pem".into(), salt(), None, Some("192.168.180.44".into()));
		assert_eq!(m.pending_clients()[0].address.as_deref(), Some("192.168.180.44"));
	}

	#[test]
	fn pending_clients_tolerates_a_missing_address() {
		let m = manager();
		m.add_pending("3344".into(), "pem".into(), salt(), None, None);
		assert_eq!(m.pending_clients()[0].address, None);
	}

	#[tokio::test]
	async fn adding_a_pending_client_signals_a_change() {
		let m = manager();
		let notify = m.pending_changed();
		let waiter = tokio::spawn(async move { notify.notified().await });
		tokio::task::yield_now().await;
		m.add_pending("EEFF".into(), "pem".into(), salt(), None, None);
		tokio::time::timeout(std::time::Duration::from_secs(1), waiter)
			.await
			.expect("pending_changed did not fire within 1s")
			.unwrap();
	}

	/// Plays the client's side of the whole GameStream pairing handshake
	/// using the crate's own crypto helpers, driving `check_client_pairing_secret`
	/// down its success path. That's the only place a client is removed from
	/// `pending_clients`, so it's the only way to test that removal for real
	/// rather than asserting against a call that never mutates the set.
	#[tokio::test]
	async fn pairing_removes_a_client_and_signals() {
		let (server_pem, server_key_pem) = crate::tls::create_certificate().expect("generate server cert");
		let (client_pem, client_key_pem) = crate::tls::create_certificate().expect("generate client cert");

		let m = ClientManager::new(server_pem, server_key_pem).expect("construct ClientManager");
		let id = "0011223344556677";
		let pin = "1234";
		let salt_bytes = salt();

		m.add_pending(id.into(), client_pem.clone(), salt_bytes, Some("test-client".into()), None);
		assert_eq!(m.pending_clients().len(), 1, "sanity: client is pending before pairing completes");

		m.register_pin(id, pin).expect("register pin");
		let key = create_key(&salt_bytes, pin).expect("derive key from salt and pin");

		// clientchallenge: client encrypts a nonce; server returns
		// sha256(nonce || server cert signature || server secret) || server challenge.
		let raw_challenge = [7u8; 16];
		let encrypted_challenge = aes_encrypt_ecb(&raw_challenge, &key).expect("encrypt challenge");
		let challenge_response = m.client_challenge(id, encrypted_challenge).expect("client_challenge");
		let decrypted = aes_decrypt_ecb(&challenge_response, &key).expect("decrypt challenge response");
		let server_challenge: [u8; 16] = decrypted[32..48].try_into().expect("server challenge slice");

		// serverchallengeresp: client proves it holds the key by echoing back
		// sha256(server challenge || client cert signature || client secret payload).
		let client_secret_payload = [9u8; 16];
		let client_cert_signature = extract_certificate_signature(&client_pem).expect("client cert signature");
		let mut hash_input = server_challenge.to_vec();
		hash_input.extend_from_slice(&client_cert_signature);
		hash_input.extend_from_slice(&client_secret_payload);
		let client_hash = Sha256::digest(&hash_input).to_vec();
		let encrypted_client_hash = aes_encrypt_ecb(&client_hash, &key).expect("encrypt client hash");
		m.server_challenge_response(id, encrypted_client_hash)
			.expect("server_challenge_response");

		// clientpairingsecret: client sends its secret payload signed with its
		// own private key, letting the server verify the certificate it was
		// handed at the start of pairing actually belongs to this client.
		let client_signature = sign(&client_secret_payload, &client_key_pem).expect("sign client secret payload");
		let mut client_secret = client_secret_payload.to_vec();
		client_secret.extend(client_signature);

		let notify = m.pending_changed();
		let waiter = tokio::spawn(async move { notify.notified().await });
		tokio::task::yield_now().await;

		m.check_client_pairing_secret(id, client_secret)
			.expect("check_client_pairing_secret should accept a correctly signed secret");

		tokio::time::timeout(std::time::Duration::from_secs(1), waiter)
			.await
			.expect("pending_changed did not fire within 1s")
			.unwrap();

		assert!(
			m.pending_clients().is_empty(),
			"a client that finished pairing must not stay listed as pending"
		);
	}

	/// Simulates the `getservercert` handler being cancelled mid-await, e.g.
	/// because Moonlight was quit and hyper dropped the request future. The
	/// guard's `Drop` should remove the pending entry right away and signal
	/// the change, without anyone having to wait for the TTL.
	#[tokio::test]
	async fn an_abandoned_pairing_removes_the_client_and_signals() {
		let m = manager();
		m.add_pending("ABAB".into(), "pem".into(), salt(), None, None);
		assert_eq!(m.pending_clients().len(), 1, "sanity: client is pending");

		let notify = m.pending_changed();
		let waiter = tokio::spawn(async move { notify.notified().await });
		tokio::task::yield_now().await;

		let guard = PendingClientGuard::new(m.clone(), "ABAB".into());
		drop(guard); // never disarmed: stands in for a cancelled handler future

		tokio::time::timeout(std::time::Duration::from_secs(1), waiter)
			.await
			.expect("pending_changed did not fire within 1s")
			.unwrap();

		assert!(m.pending_clients().is_empty(), "abandoned pairing must not stay listed as pending");
	}

	/// The success path (a PIN arrived) disarms the guard, so its `Drop`
	/// must not remove or re-signal a client that pairing completion already
	/// removed — that would fire `pending_changed` twice for one pairing.
	#[tokio::test]
	async fn a_disarmed_guard_does_not_remove_or_signal() {
		let m = manager();
		m.add_pending("DEAD".into(), "pem".into(), salt(), None, None);

		let guard = PendingClientGuard::new(m.clone(), "DEAD".into());
		guard.disarm();

		// Stand in for `check_client_pairing_secret` being the sole remover.
		assert!(m.remove_pending("DEAD"), "sanity: the client was still pending");

		let notify = m.pending_changed();
		let waiter = tokio::spawn(async move {
			tokio::time::timeout(std::time::Duration::from_millis(200), notify.notified())
				.await
		});
		let fired = waiter.await.unwrap();
		assert!(fired.is_err(), "a disarmed, already-removed guard must not fire pending_changed again");
	}

	/// Backstop for clients that vanish without the TCP connection noticing
	/// (device sleeps, WiFi drops, a NAT keeps the socket open). Reading
	/// `pending_clients()` should sweep anything older than
	/// `PENDING_CLIENT_TTL` and signal the change.
	#[tokio::test]
	async fn a_stale_pending_client_expires_and_signals() {
		let m = manager();
		m.add_pending("F00D".into(), "pem".into(), salt(), None, None);

		{
			let mut inner = m.pending_clients.write().unwrap();
			let client = inner.get_mut("F00D").unwrap();
			client.created_at = Instant::now() - PENDING_CLIENT_TTL - Duration::from_secs(1);
		}

		let notify = m.pending_changed();
		let waiter = tokio::spawn(async move { notify.notified().await });
		tokio::task::yield_now().await;

		assert!(m.pending_clients().is_empty(), "stale pending client should have been expired");

		tokio::time::timeout(std::time::Duration::from_secs(1), waiter)
			.await
			.expect("pending_changed did not fire within 1s")
			.unwrap();
	}

	/// A pending client well within the TTL must not be swept.
	#[tokio::test]
	async fn a_fresh_pending_client_is_not_expired() {
		let m = manager();
		m.add_pending("C0DE".into(), "pem".into(), salt(), None, None);
		assert_eq!(m.pending_clients().len(), 1, "a fresh client must not be expired");
	}
}
